  if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') blink();
  if (e.code === 'ControlLeft' || e.code === 'ControlRight') sprint = true;
  if (e.code === 'KeyE') tryInteract();
}
function onKeyUp(e) {
  keys.delete(e.code);
  if (e.code === 'ControlLeft' || e.code === 'ControlRight') sprint = false;
}

